-- =========================================================
-- yuqing_db 数据库初始化脚本
-- 项目：anime-login-vue 前端 + springBootTest 后端
-- 说明：
--   1. 前两句（创建 yuqing 用户 + 授权）需要 root 权限执行一次；
--      如果 yuqing 用户已存在，可跳过。
--   2. 建库建表语句用 yuqing 或 root 执行均可。
--   3. 后端启动时会自动初始化测试账号 sakura / Test@123456，
--      无需手工插入用户数据。
--   4. 番剧表 bangumi 含 12 部作品的插画（cover_svg 内联 SVG 源码），
--      重复执行本脚本会重建种子数据，插画可直接覆盖更新。
-- =========================================================

-- 创建应用专用账号（root 执行，已存在则忽略）
CREATE USER IF NOT EXISTS 'yuqing'@'localhost' IDENTIFIED BY '123456';
CREATE USER IF NOT EXISTS 'yuqing'@'%' IDENTIFIED BY '123456';

-- 创建数据库
CREATE DATABASE IF NOT EXISTS yuqing_db
    DEFAULT CHARACTER SET utf8mb4
    COLLATE utf8mb4_general_ci;

-- 授权（root 执行）
GRANT ALL PRIVILEGES ON yuqing_db.* TO 'yuqing'@'localhost';
GRANT ALL PRIVILEGES ON yuqing_db.* TO 'yuqing'@'%';
FLUSH PRIVILEGES;

USE yuqing_db;

-- 用户表
CREATE TABLE IF NOT EXISTS sys_user (
    id          BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
    username    VARCHAR(32)  NOT NULL                COMMENT '登录用户名',
    email       VARCHAR(64)  DEFAULT NULL            COMMENT '邮箱（可空）',
    password    VARCHAR(100) NOT NULL                COMMENT '密码（BCrypt 加密存储）',
    nickname    VARCHAR(32)  DEFAULT NULL            COMMENT '展示昵称',
    status      TINYINT      NOT NULL DEFAULT 1      COMMENT '状态：1 正常，0 禁用',
    create_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP                COMMENT '创建时间',
    update_time DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
                             ON UPDATE CURRENT_TIMESTAMP                       COMMENT '更新时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_username (username),
    UNIQUE KEY uk_email (email)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COMMENT = '用户表';


-- =========================================================
-- 视频表 + 每日推荐种子数据（首页热门推荐 / 每日推荐 数据源）
-- 说明：id 与前端 mock 数据保持一致（1~8），切换真实后端时前端页面无需任何改动。
-- =========================================================

CREATE TABLE IF NOT EXISTS video (
    id              BIGINT       NOT NULL AUTO_INCREMENT COMMENT '主键',
    title           VARCHAR(200) NOT NULL                COMMENT '标题',
    uploader        VARCHAR(64)  DEFAULT ''              COMMENT 'UP 主 / 投稿方',
    views           VARCHAR(32)  DEFAULT ''              COMMENT '播放量展示文案（如 128.5万）',
    play            BIGINT       DEFAULT 0               COMMENT '真实播放量（用于排行排序）',
    danmaku         VARCHAR(32)  DEFAULT ''              COMMENT '弹幕数展示文案（如 3.2万）',
    duration        VARCHAR(16)  DEFAULT ''              COMMENT '时长（如 04:12）',
    tags            VARCHAR(128) DEFAULT ''              COMMENT '标签，逗号分隔',
    description     VARCHAR(500) DEFAULT ''              COMMENT '简介',
    fav             TINYINT      NOT NULL DEFAULT 0      COMMENT '是否收藏：1 收藏，0 否',
    grad            VARCHAR(128) DEFAULT ''              COMMENT '封面渐变 CSS（如 linear-gradient(...)）',
    src             VARCHAR(255) DEFAULT ''              COMMENT '播放地址',
    daily_pick      TINYINT      NOT NULL DEFAULT 1      COMMENT '是否每日推荐：1 推荐，0 否',
    recommend_date  DATE         DEFAULT NULL            COMMENT '推荐日期（每日推荐轮换用）',
    create_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP                COMMENT '创建时间',
    update_time     DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP
                                ON UPDATE CURRENT_TIMESTAMP                       COMMENT '更新时间',
    PRIMARY KEY (id)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COMMENT = '视频表';

-- 种子数据（重复执行会先清空再插入，方便后续更新）
