-- =========================================================
-- 番剧表 + 12 部番剧插画种子数据
-- 说明：
--   1. cover_svg 存放插画的完整 SVG 源码（3:4 竖版海报），
--      自包含、不依赖任何静态资源目录，后端可直接取出返回。
--   2. 取图优先级：cover_url（外部图）> cover_svg（内联插画）
--      > cover_gradient（纯 CSS 渐变兜底）。
--   3. id 与前端 mock 数据保持一致（101~112），改用真实后端
--      时前端页面无需任何改动。
-- =========================================================

CREATE TABLE IF NOT EXISTS bangumi (
    id             BIGINT        NOT NULL AUTO_INCREMENT COMMENT '主键（101~112，与前端 mock 数据一致）',
    title          VARCHAR(64)   NOT NULL                COMMENT '番剧标题',
    cover_svg      LONGTEXT      DEFAULT NULL            COMMENT '番剧插画：内联 SVG 源码（3:4 竖版海报）',
    cover_url      VARCHAR(255)  DEFAULT NULL            COMMENT '外部封面图 URL，有值时优先于 cover_svg',
    cover_gradient VARCHAR(200)  DEFAULT NULL            COMMENT 'CSS 渐变封面，无图时兜底展示',
    episodes       INT           NOT NULL DEFAULT 12     COMMENT '总集数',
    status         VARCHAR(16)   NOT NULL DEFAULT '连载中' COMMENT '连载中 / 已完结',
    score          DECIMAL(3, 1) NOT NULL DEFAULT 8.0    COMMENT '评分',
    studio         VARCHAR(64)   DEFAULT NULL            COMMENT '制作公司',
    category       VARCHAR(16)   DEFAULT NULL            COMMENT '分类：日漫 / 国漫 / 剧场 / 美漫',
    tags           VARCHAR(128)  DEFAULT NULL            COMMENT '标签，斜杠分隔',
    description    VARCHAR(500)  DEFAULT NULL            COMMENT '简介',
    create_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP                COMMENT '创建时间',
    update_time    DATETIME      NOT NULL DEFAULT CURRENT_TIMESTAMP
                                 ON UPDATE CURRENT_TIMESTAMP                       COMMENT '更新时间',
    PRIMARY KEY (id),
    KEY idx_category (category),
    KEY idx_status (status)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COMMENT = '番剧表';

