-- =========================================================
-- 番剧放送时间表 + 种子数据
-- 说明：
--   1. weekday 用 1~7 表示周一~周日（与 Java DayOfWeek 对齐）。
--   2. 与 bangumi 表用 bangumi_id 关联（不建外键，方便单独清数据）。
--   3. 首页"番剧时间表"侧栏读取此表，返回结构：
--      { weekdays, today, items: { 周一: [{ title, ep, time }] } }
-- =========================================================

CREATE TABLE IF NOT EXISTS bangumi_schedule (
    id          BIGINT      NOT NULL AUTO_INCREMENT COMMENT '主键',
    bangumi_id  BIGINT      NOT NULL                COMMENT '番剧 id，逻辑关联 bangumi.id',
    weekday     TINYINT     NOT NULL                COMMENT '放送日：1=周一 … 7=周日',
    air_time    VARCHAR(8)  NOT NULL                COMMENT '放送时间 HH:mm',
    episode     INT         NOT NULL DEFAULT 1      COMMENT '当日更新至第几话',
    create_time DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP                COMMENT '创建时间',
    update_time DATETIME    NOT NULL DEFAULT CURRENT_TIMESTAMP
                            ON UPDATE CURRENT_TIMESTAMP                       COMMENT '更新时间',
    PRIMARY KEY (id),
    UNIQUE KEY uk_bangumi_weekday (bangumi_id, weekday),
    KEY idx_weekday (weekday)
) ENGINE = InnoDB
  DEFAULT CHARSET = utf8mb4
  COMMENT = '番剧放送时间表';

